      const rx = sampleQuintic1D(tc, times[seg], times[seg+1], pts[seg].x, vels[seg].x, accs[seg].x, pts[seg+1].x, vels[seg+1].x, accs[seg+1].x);
      const ry = sampleQuintic1D(tc, times[seg], times[seg+1], pts[seg].y, vels[seg].y, accs[seg].y, pts[seg+1].y, vels[seg+1].y, accs[seg+1].y);
      const rz = sampleQuintic1D(tc, times[seg], times[seg+1], pts[seg].z, vels[seg].z, accs[seg].z, pts[seg+1].z, vels[seg+1].z, accs[seg+1].z);
      return { pos: { x: rx.pos, y: ry.pos, z: rz.pos }, vel: { x: rx.vel, y: ry.vel, z: rz.vel }, acc: { x: rx.acc, y: ry.acc, z: rz.acc } };
    };
    const sp = evalSpline(obs.t);
    for (const axis of ["x", "y", "z"]) intErr[axis] = clamp(intErr[axis] + (sp.pos[axis] - obs.pos[axis]) * 0.01, -0.4, 0.4);
    const kp = 18, kd = 8.0, ki = 5;
